  "Vollkornbrot": [["Ich esse gern Vollkornbrot.", "Обичам да ям пълнозърнест хляб."], ["Das Vollkornbrot ist frisch.", "Пълнозърнестият хляб е пресен."], ["Eine Scheibe Vollkornbrot, bitte.", "Една филия пълнозърнест хляб, моля."]],
  "Weißbrot": [["Weißbrot ist nicht so gesund.", "Белият хляб не е толкова здравословен."], ["Ich nehme Weißbrot mit Butter.", "Взимам бял хляб с масло."], ["Die Kinder essen gern Weißbrot.", "Децата обичат бял хляб."]],
  "Toastbrot": [["Das Toastbrot ist warm.", "Препеченият хляб е топъл."], ["Ich esse Toastbrot mit Honig.", "Ям тост с мед."], ["Gibt es auch Toastbrot?", "Има ли и хляб за тост?"]],
